// Written by scripts/app-css.mjs from apps/web's stylesheets: don't edit it by hand.
export const APP_CSS = "/* apps/web/src/shell/base.css */\n/*\n * Tokens (plan #style). The theme (T28: packages/ui/src/theme) sets every\n * colour, the fonts and the editor width on <html> (`--pm-bg`, `--pm-fg`,\n * `--pm-accent`…, see COLOUR_TOKENS) along with `data-mode` (light or dark).\n * Everything here is derived from those with color-mix, so each theme gets\n * the same hover, pressed, focus, soft and shadow states. Stylesheets never\n * write a colour literally (stylelint, A244).\n */\n:root {\n  color-scheme: light dark;\n  /* The note's status bar (A505): toasts float above it. */\n  --status-bar-height: 1.8rem;\n  --pm-hover: color-mix(in oklab, var(--pm-fg) 6%, transparent);\n  --pm-code-bg: color-mix(in oklab, var(--pm-bg), var(--pm-fg) 6%);\n  --pm-focus: color-mix(in oklab, var(--pm-accent) 70%, var(--pm-fg));\n  --pm-active: color-mix(in oklab, var(--pm-fg) 9%, transparent);\n  --pm-drop: color-mix(in oklab, var(--pm-accent) 14%, transparent);\n  --pm-radius: 0;\n  --pm-scrim: color-mix(in oklab, var(--pm-shadow-color) 28%, transparent);\n  --pm-shadow: 0 12px 40px color-mix(in oklab, var(--pm-shadow-color) 22%, transparent);\n  --pm-accent-soft: color-mix(in oklab, var(--pm-accent) 14%, transparent);\n  --pm-accent-line: color-mix(in oklab, var(--pm-accent) 45%, transparent);\n  /* Agent edits (T24): a colour of their own, apart from the accent and the user's selection. */\n  --pm-agent-soft: color-mix(in oklab, var(--pm-agent) 22%, transparent);\n  /* T36: the fidelity pass (A182). Derived colours, after the prototype's. */\n  --pm-border-strong: color-mix(in oklab, var(--pm-border), var(--pm-fg) 15%);\n  --pm-border-soft: color-mix(in oklab, var(--pm-border), var(--pm-bg) 45%);\n  --pm-danger-soft: color-mix(in oklab, var(--pm-danger) 12%, transparent);\n  --pm-accent-softer: color-mix(in oklab, var(--pm-accent) 8%, transparent);\n  --pm-ring: 0 0 0 3px color-mix(in oklab, var(--pm-accent) 18%, transparent);\n  --pm-shadow-1: 0 1px 2px color-mix(in oklab, var(--pm-shadow-color) 8%, transparent);\n  /* Shape. */\n  --pm-radius-sm: 0;\n  --pm-radius-lg: 0;\n  --pm-radius-xl: 0;\n  --pm-radius-sheet: 0;\n  /* Controls: buttons and fields, and the touch size on phones (44 px, A183). */\n  --pm-control: 2rem;\n  --pm-control-sm: 1.75rem;\n  --pm-hit: 2.75rem;\n  --pm-bar: 3.5rem;\n  --pm-ease: cubic-bezier(0.2, 0.7, 0.2, 1);\n  --pm-fast: 120ms;\n  --pm-medium: 200ms;\n}\n\n/* Shadows read heavier on dark surfaces. */\n:root[data-mode='dark'] {\n  --pm-shadow-1: 0 1px 2px color-mix(in oklab, var(--pm-shadow-color) 30%, transparent);\n}\n\nbody {\n  margin: 0;\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n  font-family: var(--pm-font);\n  /* Text that names no role of its own is running text (type.css, A1561). */\n  font-size: var(--pm-text-body);\n  -webkit-font-smoothing: antialiased;\n  -webkit-tap-highlight-color: transparent;\n}\n\na {\n  color: var(--pm-link, var(--pm-accent));\n}\n\n.app-shell {\n  max-width: 40rem;\n  margin: 0 auto;\n  padding: max(3rem, env(safe-area-inset-top)) 1rem 3rem;\n}\n\n.app-shell h1 {\n  margin: 0 0 0.5rem;\n  font-size: var(--pm-text-page-title);\n  letter-spacing: -0.01em;\n}\n\n.app-shell p {\n  color: var(--pm-muted);\n  margin: 0;\n}\n\n/* A section's sub-headings, one step below its title in every section (T39 pass 2). */\n.settings h3,\n.settings-section h3 {\n  margin: 2rem 0 0.5rem;\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n}\n\n/*\n * Devices' too, past its empty status line: its first sub-heading sat 32px under the title,\n * Status's 20px (A988).\n */\n.settings h2 + h3,\n.settings h2 + p:empty + h3,\n.settings-section h2 + h3 {\n  margin-top: 1.25rem;\n}\n\n.settings p {\n  margin: 0.25rem 0 0.75rem;\n}\n\n.list {\n  margin: 0 0 1rem;\n  padding: 0;\n  overflow: hidden;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  list-style: none;\n}\n\n.list:empty {\n  display: none;\n}\n\n.list li {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n  min-height: 3.25rem;\n  padding: 0.5rem 0.75rem;\n  border-bottom: 1px solid var(--pm-border-soft);\n  font-size: var(--pm-text-item);\n}\n\n.list li:last-child {\n  border-bottom: 0;\n}\n\n.list small {\n  color: var(--pm-muted);\n}\n\n.row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  align-items: center;\n}\n\n.secret {\n  margin: 1rem 0;\n  padding: 0.85rem 1rem;\n  border: 1px solid var(--pm-accent-line);\n  border-radius: 0;\n  background: var(--pm-accent-softer);\n}\n\n.secret code {\n  display: block;\n  margin: 0.5rem 0 0.75rem;\n  padding: 0.5rem 0.65rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-code);\n  overflow-wrap: anywhere;\n}\n\n.error {\n  color: var(--pm-danger);\n}\n\n/* apps/web/src/shell/type.css */\n/*\n * Type (A1561): one scale, and the roles every screen's text takes from it. A stylesheet never\n * writes a font size, weight or line height itself (stylelint, scripts/stylelint-type.mjs): it\n * names the role its text plays (`--pm-text-help`, or the `t-help` class), or for a one-off\n * (a glyph, a miniature) a step of the scale. So a note under a setting is the same size as\n * every other note under a setting, and a child is never larger than its parent's heading.\n *\n * The note's own text (its title, headings, code, the margin's symbols) has a scale of its own\n * at the end, relative to the Note Font Size (A944); it is the note's typography, not chrome.\n */\n:root {\n  /* The scale: the prototype's 11.5, 13, 14 and 16 px (A182), and a step or two either side. */\n  --pm-text-2xs: 0.65rem; /* 10.4 px */\n  --pm-text-xs: 0.72rem; /* 11.5 px */\n  --pm-text-sm: 0.8125rem; /* 13 px */\n  --pm-text-md: 0.875rem; /* 14 px */\n  --pm-text-lg: 1rem; /* 16 px */\n  --pm-text-xl: 1.125rem; /* 18 px */\n  --pm-text-2xl: 1.25rem; /* 20 px */\n  --pm-text-3xl: 1.5rem; /* 24 px */\n  --pm-text-4xl: 1.75rem; /* 28 px */\n  --pm-text-5xl: 2rem; /* 32 px */\n  --pm-weight-regular: 400;\n  --pm-weight-medium: 500;\n  --pm-weight-semibold: 600;\n  --pm-weight-bold: 700;\n  --pm-leading-none: 1;\n  --pm-leading-tight: 1.25;\n  --pm-leading-snug: 1.4;\n  --pm-leading-relaxed: 1.5;\n\n  /*\n   * The roles, largest first. Each has a size, a weight and a line height (`normal` where the\n   * text sits in a row whose height is set elsewhere), and a colour where the role has one.\n   */\n  /* A page's title: Settings, Trash, Tags, the welcome. */\n  --pm-text-page-title: var(--pm-text-5xl);\n  --pm-weight-page-title: var(--pm-weight-bold);\n  --pm-leading-page-title: var(--pm-leading-tight);\n  /* The page's title again, small, in a bar pinned over the page once it scrolls. */\n  --pm-text-bar-title: var(--pm-text-xl);\n  --pm-weight-bar-title: var(--pm-weight-bold);\n  --pm-leading-bar-title: var(--pm-leading-tight);\n  /* A section of a page: a Settings page's own title (Appearance, Sidebar…). */\n  --pm-text-section-head: var(--pm-text-xl);\n  --pm-weight-section-head: var(--pm-weight-bold);\n  --pm-leading-section-head: var(--pm-leading-tight);\n  /* A group within a section (Shortcuts, Sections), a card's title. */\n  --pm-text-group-head: var(--pm-text-lg);\n  --pm-weight-group-head: var(--pm-weight-semibold);\n  --pm-leading-group-head: var(--pm-leading-tight);\n  /* A dialog's or a sheet's title. */\n  --pm-text-dialog-title: var(--pm-text-lg);\n  --pm-weight-dialog-title: var(--pm-weight-semibold);\n  --pm-leading-dialog-title: var(--pm-leading-tight);\n  /* Running text: a page's or a dialog's paragraphs. */\n  --pm-text-body: var(--pm-text-md);\n  --pm-weight-body: var(--pm-weight-regular);\n  --pm-leading-body: var(--pm-leading-relaxed);\n  /* A setting's or a field's name. */\n  --pm-text-row-label: var(--pm-text-sm);\n  --pm-weight-row-label: var(--pm-weight-semibold);\n  --pm-leading-row-label: normal;\n  /* A thing you pick or press: a menu item, a button, a list or table row, a tab, a toast. */\n  --pm-text-item: var(--pm-text-sm);\n  --pm-weight-item: var(--pm-weight-regular);\n  --pm-leading-item: normal;\n  /* A row of the sidebar: its notes, folders, tags and shortcuts. */\n  --pm-text-sidebar-item: var(--pm-text-sm);\n  /* What you type into: fields and selects. */\n  --pm-text-field: var(--pm-text-sm);\n  /* What a row, a group or a panel means: a setting's help, a note under a form, a hint. */\n  --pm-text-help: var(--pm-text-xs);\n  --pm-weight-help: var(--pm-weight-regular);\n  --pm-leading-help: var(--pm-leading-snug);\n  --pm-color-help: var(--pm-muted);\n  /* About a thing, beside or under it: a time, a count, a path, a status, a caption. */\n  --pm-text-meta: var(--pm-text-xs);\n  --pm-weight-meta: var(--pm-weight-regular);\n  --pm-leading-meta: normal;\n  --pm-color-meta: var(--pm-muted);\n  /* A list's heading over its items: a sidebar section, a menu's group, a panel's heading. */\n  --pm-text-list-head: var(--pm-text-xs);\n  --pm-weight-list-head: var(--pm-weight-semibold);\n  --pm-leading-list-head: normal;\n  --pm-color-list-head: var(--pm-muted);\n  /* A chip, a key cap, a scope marker. */\n  --pm-text-badge: var(--pm-text-xs);\n  --pm-weight-badge: var(--pm-weight-semibold);\n  --pm-leading-badge: normal;\n  /* A count on a tab or an icon, and the text of a miniature. */\n  --pm-text-micro: var(--pm-text-2xs);\n  --pm-weight-micro: var(--pm-weight-semibold);\n  /* A tooltip. */\n  --pm-text-tooltip: var(--pm-text-xs);\n  --pm-weight-tooltip: var(--pm-weight-medium);\n  --pm-leading-tooltip: var(--pm-leading-snug);\n  /* Code and other monospaced text in the chrome: a diff, a source, a command. */\n  --pm-text-code: var(--pm-text-sm);\n  --pm-leading-code: var(--pm-leading-relaxed);\n  /* Code inside a line of chrome text. */\n  --pm-text-code-inline: 0.85em;\n  /* A code to read out or type somewhere else (GitHub's device code). */\n  --pm-text-display: var(--pm-text-4xl);\n  --pm-weight-display: var(--pm-weight-semibold);\n  /* A notebook badge's letter, as a share of its square (badge.css). */\n  --pm-badge-glyph-ratio: 0.62;\n\n  /*\n   * The note's own scale, from the Note Font Size (A944): the title a step above a first\n   * heading (A554), headings in em of the text, code a little smaller than it.\n   */\n  --pm-note-text-size: var(--pm-note-size, 16px);\n  --pm-note-leading: 1.7;\n  --pm-note-title-size: calc(var(--pm-note-size, 16px) * 1.9);\n  --pm-note-title-weight: var(--pm-weight-bold);\n  --pm-note-title-leading: 1.2;\n  --pm-note-h1-size: 1.6em;\n  --pm-note-h2-size: 1.28em;\n  --pm-note-h3-size: 1.07em;\n  --pm-note-heading-leading: 1.3;\n  --pm-note-code-size: 0.86em;\n  --pm-note-code-leading: 1.55;\n  /* A callout's type and title, in the interface font. */\n  --pm-note-callout-type-size: 0.92rem;\n  --pm-note-callout-title-size: 0.95rem;\n  /*\n   * The gutter's symbols (A1680): one size on every line, a little under the note's text, so\n   * the gutter's three slots hold a heading's too; their line height is the line's own, so they\n   * sit level with its text. Their \"+N\" in em of them.\n   */\n  --pm-note-symbol-size: calc(var(--pm-note-size, 16px) * 0.9);\n  --pm-note-symbol-leading: 1lh;\n  --pm-note-symbol-more-size: 0.7em;\n  --pm-note-symbol-badge-size: 0.6em;\n  /* A gutter slot in em of the note's text: a glyph's 1.1em and its gap, an emoji's width. */\n  --pm-note-symbol-slot: 1.125em;\n  /* The widget's padding and the gap it keeps from the text. */\n  --pm-note-symbol-gutter-gap: calc(0.2em + 0.3rem);\n  /* An agent's name on its edit. */\n  --pm-note-agent-label-size: 0.7em;\n  /* Appearance's preview of a note, a little under the note's own sizes. */\n  --pm-note-preview-title-size: calc(var(--pm-note-size, 16px) * 1.15);\n  --pm-note-preview-text-size: calc(var(--pm-note-size, 16px) * 0.875);\n  --pm-note-preview-code-size: calc(var(--pm-note-size, 16px) * 0.85);\n}\n\n/* Phones: titles a step smaller, and the note's title a little under the desktop's (A554). */\n@media (max-width: 700px) {\n  :root {\n    --pm-text-page-title: var(--pm-text-3xl);\n    --pm-note-title-size: calc(var(--pm-note-size, 16px) * 1.85);\n  }\n}\n\n/* Touch: the sidebar's rows a step larger, and fields at 16 px so iOS never zooms into them. */\n@media (max-width: 700px), (pointer: coarse) {\n  :root {\n    --pm-text-sidebar-item: var(--pm-text-md);\n    --pm-text-field: var(--pm-text-lg);\n  }\n}\n\n/*\n * The roles as classes, for an element whose stylesheet has nothing else to say about it\n * (`<p className=\"t-help\">`). Each sets the role's size, weight, line height and colour.\n */\n.t-page-title {\n  font-size: var(--pm-text-page-title);\n  font-weight: var(--pm-weight-page-title);\n  line-height: var(--pm-leading-page-title);\n}\n\n.t-bar-title {\n  font-size: var(--pm-text-bar-title);\n  font-weight: var(--pm-weight-bar-title);\n  line-height: var(--pm-leading-bar-title);\n}\n\n.t-section-head {\n  font-size: var(--pm-text-section-head);\n  font-weight: var(--pm-weight-section-head);\n  line-height: var(--pm-leading-section-head);\n}\n\n.t-group-head {\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n  line-height: var(--pm-leading-group-head);\n}\n\n.t-dialog-title {\n  font-size: var(--pm-text-dialog-title);\n  font-weight: var(--pm-weight-dialog-title);\n  line-height: var(--pm-leading-dialog-title);\n}\n\n.t-body {\n  font-size: var(--pm-text-body);\n  font-weight: var(--pm-weight-body);\n  line-height: var(--pm-leading-body);\n}\n\n.t-row-label {\n  font-size: var(--pm-text-row-label);\n  font-weight: var(--pm-weight-row-label);\n  line-height: var(--pm-leading-row-label);\n}\n\n.t-item {\n  font-size: var(--pm-text-item);\n  font-weight: var(--pm-weight-item);\n  line-height: var(--pm-leading-item);\n}\n\n.t-help {\n  color: var(--pm-color-help);\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-help);\n  line-height: var(--pm-leading-help);\n}\n\n.t-meta {\n  color: var(--pm-color-meta);\n  font-size: var(--pm-text-meta);\n  font-weight: var(--pm-weight-meta);\n  line-height: var(--pm-leading-meta);\n}\n\n.t-list-head {\n  color: var(--pm-color-list-head);\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n  line-height: var(--pm-leading-list-head);\n}\n\n.t-badge {\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-badge);\n  line-height: var(--pm-leading-badge);\n}\n\n.t-code {\n  font-family: var(--pm-mono);\n  font-size: var(--pm-text-code);\n  line-height: var(--pm-leading-code);\n}\n\n/* apps/web/src/shell/shell.css */\n/* Notes shell (T6): sidebar with the note list, and the open note. Loosely after prototype/. */\n.notes-app {\n  display: grid;\n  /* The sidebar's width, dragged by its edge (A1122): set on the element, 17rem until then. */\n  grid-template-columns: var(--pm-sidebar-width, 17rem) minmax(0, 1fr);\n  height: 100vh;\n  height: 100dvh;\n}\n\n/*\n * The page is a column the window's height (the T39 review, T41): whatever sits above the\n * notes (the \"Sign in again\" banner) takes its own height and the notes take the rest, so the\n * page never scrolls as a whole. Other screens (Settings pages, sign-in approval) keep their\n * own height and the page scrolls past it as before.\n */\n#root {\n  display: flex;\n  flex-direction: column;\n  height: 100vh;\n  height: 100dvh;\n}\n\n#root > .notes-app {\n  flex: 1 1 0;\n  min-height: 0;\n  height: auto;\n}\n\n#root > .app-shell,\n#root > .settings-shell {\n  box-sizing: border-box;\n  width: 100%;\n}\n\n/*\n * A window with none of the app in it yet (the wait for the notebooks, the first run; FirstRun.tsx):\n * what it shows scrolls in `.window-bare`, under `.window-drag`, a strip across the window's top\n * that drags it with the compact title bar (Ryan's review of #192, finding 1). Without that title\n * bar the strip takes no room.\n */\n#root > .window-drag {\n  display: none;\n}\n\n:root[data-titlebar='compact'] #root > .window-drag {\n  display: block;\n  flex: none;\n  height: var(--pm-titlebar-row);\n}\n\n#root > .window-bare {\n  flex: 1 1 0;\n  min-height: 0;\n  overflow-y: auto;\n}\n\n.window-bare > .app-shell {\n  box-sizing: border-box;\n}\n\n.sidebar {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  background: var(--pm-sidebar);\n  border-right: 1px solid var(--pm-border);\n}\n\n.sb-head {\n  display: flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.75rem 0.5rem 0.4rem 0.875rem;\n}\n\n.brand {\n  display: flex;\n  flex: 1;\n  align-items: center;\n  gap: 0.5rem;\n  min-width: 0;\n  margin: 0;\n  color: var(--pm-fg);\n  font-size: var(--pm-text-md);\n  font-weight: var(--pm-weight-semibold);\n  letter-spacing: -0.01em;\n}\n\n/* The logo (A402): its light tile, or its dark one in dark mode (data-mode, else the system's). */\n.brand-mark {\n  display: flex;\n  flex: none;\n}\n\n.brand-mark > img {\n  display: block;\n}\n\n.brand-mark > .brand-mark-dark,\n:root[data-mode='dark'] .brand-mark > .brand-mark-light {\n  display: none;\n}\n\n:root[data-mode='dark'] .brand-mark > .brand-mark-dark {\n  display: block;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not([data-mode]) .brand-mark > .brand-mark-light {\n    display: none;\n  }\n\n  :root:not([data-mode]) .brand-mark > .brand-mark-dark {\n    display: block;\n  }\n}\n\n/* Only in the phone's drawer (below); the specificity outranks .icon-btn's display. */\n.sb-head .drawer-close {\n  display: none;\n}\n\n.sb-actions {\n  display: grid;\n  gap: 1px;\n  padding: 0.25rem 0.5rem 0.5rem;\n}\n\n/*\n * New Note, then Search, Today, This Week, Graph, Notebooks and Commands, and ⋯ at the end: one\n * row of icons (T51, A932; T52; T53). The icons give up a little width rather than wrap: with\n * no `min-width` the row, a grid item, kept its icons' full widths and ran past the sidebar's\n * edge, cutting ⋯ off (T53 pass).\n */\n.sb-shortcuts {\n  display: flex;\n  min-width: 0;\n  gap: 2px;\n}\n\n.sb-shortcuts .sb-shortcut:not(.new-note) {\n  flex: 0 1 var(--pm-control);\n  min-width: 1.5rem;\n}\n\n/* New Note leads the row in the accent's fill, as the primary button did (T52). */\n.sb-shortcut.new-note {\n  margin-inline-end: 0.3rem;\n  background: var(--pm-accent);\n  color: var(--pm-on-accent);\n}\n\n.sb-shortcut.new-note:hover:not(:disabled) {\n  background: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 12%);\n  color: var(--pm-on-accent);\n}\n\n.sb-shortcut.new-note:active:not(:disabled) {\n  background: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 20%);\n  color: var(--pm-on-accent);\n}\n\n.sb-shortcut[aria-current='page'],\n.sb-foot .icon-btn[aria-current='page'] {\n  background: var(--pm-active);\n  color: var(--pm-fg);\n}\n\n/* Back and Forward at the start of the sidebar's head, the window's first row (T51, A943). */\n.history-nav {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 2px;\n}\n\n/*\n * Back and Forward as one compact pair (T52): two half-width buttons on one quiet chip, a hairline\n * between them, each still 28 px tall with its own hover, focus ring and disabled state.\n */\n.history-pair {\n  display: inline-flex;\n  flex: none;\n  height: var(--pm-control-sm);\n  border-radius: 0;\n  background: color-mix(in oklab, var(--pm-fg) 5%, transparent);\n}\n\n.history-pair .history-half {\n  position: relative;\n  width: 1.375rem;\n  height: 100%;\n  border-radius: 0;\n}\n\n.history-pair .history-half:first-child {\n  border-radius: 0;\n}\n\n.history-pair .history-half:last-child {\n  border-radius: 0;\n}\n\n.history-pair .history-half + .history-half::before {\n  position: absolute;\n  top: 25%;\n  bottom: 25%;\n  left: 0;\n  width: 1px;\n  background: var(--pm-border);\n  content: '';\n}\n\n/* The ring above the other half. */\n.history-pair .history-half:focus-visible {\n  z-index: 1;\n}\n\n@media (max-width: 700px), (pointer: coarse) {\n  .history-pair {\n    height: var(--pm-hit);\n  }\n\n  .history-pair .history-half {\n    width: 2.25rem;\n    height: 100%;\n  }\n}\n\n/*\n * Buttons (T36): one height, radius and set of states, light and dark. Border-box, so a link\n * drawn as a button is the height of a real one, not 2px taller (A988).\n */\n.btn {\n  display: inline-flex;\n  flex: none;\n  box-sizing: border-box;\n  align-items: center;\n  justify-content: center;\n  gap: 0.4rem;\n  height: var(--pm-control);\n  padding: 0 0.75rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  box-shadow: var(--pm-shadow-1);\n  color: var(--pm-fg);\n  font: inherit;\n  font-size: var(--pm-text-item);\n  font-weight: var(--pm-weight-medium);\n  white-space: nowrap;\n  text-decoration: none;\n  cursor: pointer;\n  transition:\n    background var(--pm-fast),\n    border-color var(--pm-fast),\n    color var(--pm-fast);\n}\n\n.btn:hover {\n  border-color: var(--pm-border-strong);\n}\n\n.btn:active {\n  background: color-mix(in oklab, var(--pm-raised), var(--pm-fg) 6%);\n}\n\n.btn:disabled,\n.icon-btn:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n\n.btn.primary {\n  border-color: var(--pm-accent);\n  background: var(--pm-accent);\n  color: var(--pm-on-accent);\n}\n\n.btn.primary:hover:not(:disabled) {\n  background: color-mix(in oklab, var(--pm-accent), var(--pm-fg) 12%);\n}\n\n.btn.danger {\n  color: var(--pm-danger);\n}\n\n.btn.danger:hover:not(:disabled) {\n  border-color: color-mix(in oklab, var(--pm-danger) 45%, transparent);\n  background: var(--pm-danger-soft);\n}\n\n/* Solid red: an action that deletes (Delete Model…, a confirm's Delete; A1595). */\n.btn.danger-fill {\n  border-color: var(--pm-danger);\n  background: var(--pm-danger);\n  color: var(--pm-on-accent);\n}\n\n.btn.danger-fill:hover:not(:disabled) {\n  border-color: color-mix(in oklab, var(--pm-danger), var(--pm-fg) 12%);\n  background: color-mix(in oklab, var(--pm-danger), var(--pm-fg) 12%);\n}\n\n.btn kbd {\n  font-family: var(--pm-font);\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-medium);\n  line-height: var(--pm-leading-none);\n  opacity: 0.8;\n}\n\n/* On the accent, a key is outlined in the button's own text colour (4.5:1, not faded). */\n.btn.primary .keys kbd {\n  border-color: color-mix(in oklab, var(--pm-on-accent) 45%, transparent);\n  background: transparent;\n  color: var(--pm-on-accent);\n  opacity: 1;\n}\n\n.btn .i,\n.icon-btn .i,\n.sb-item .i,\n.menu-item .i {\n  flex: none;\n}\n\n:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 1px;\n}\n\n/* Sidebar rows (T36, after the prototype): an icon, a label, and keys on hover or focus. */\n.sb-item {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  width: 100%;\n  min-height: var(--pm-control-sm);\n  padding: 0 0.5rem;\n  border: 0;\n  border-radius: 0;\n  background: none;\n  color: var(--pm-muted);\n  font: inherit;\n  font-size: var(--pm-text-sidebar-item);\n  text-align: left;\n  text-decoration: none;\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.sb-item:hover {\n  background: var(--pm-hover);\n  color: var(--pm-fg);\n}\n\n.sb-item:focus-visible {\n  outline-offset: -2px;\n}\n\n.sb-item[aria-current='page'] {\n  background: var(--pm-active);\n  color: var(--pm-fg);\n  font-weight: var(--pm-weight-medium);\n}\n\n.sb-item .label {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.sb-list {\n  display: flex;\n  flex: 1;\n  flex-direction: column;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 0;\n}\n\n.list-empty {\n  margin: 0.5rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n}\n\n.note-list {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n/* apps/web/src/shell/controls.css */\n/*\n * The note's header (T36): the note's folders, then its actions, after the prototype's editor bar.\n * Its end padding is the tab strip's (links.css), so the last action sits over the strip's icons,\n * on one column (A988). In the sidebar's colour, so the title bar reads apart from the text in\n * every theme, light and dark (PEN-135 item 7).\n */\n.note-top {\n  position: sticky;\n  top: 0;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  height: 3rem;\n  padding: 0 0.3rem 0 1rem;\n  border-bottom: 1px solid var(--pm-border-soft);\n  background: var(--pm-sidebar);\n}\n\n/*\n * Beside the rail, Back, Forward and the pin start the note's title bar (PEN-135 item 6), flush\n * and as tall as the row, as in the sidebar's head (A1135): from the rail's edge, or after the\n * traffic lights' room in the Mac app, a hairline either side.\n */\n.note-top:has(> .note-top-lead) {\n  padding-left: 0;\n}\n\n.note-top-lead {\n  display: flex;\n  flex: none;\n  align-self: stretch;\n  border-right: 1px solid var(--pm-border-soft);\n}\n\n.note-top-lead .history-nav {\n  align-self: stretch;\n}\n\n.note-top-lead .history-pair {\n  height: 100%;\n  background: none;\n}\n\n.note-top-lead .history-pair .history-half {\n  width: 2rem;\n}\n\n.note-top-lead .history-half + .history-half::before {\n  top: 0;\n  bottom: 0;\n  background: var(--pm-border-soft);\n}\n\n.note-top-lead > .icon-btn {\n  width: 2.5rem;\n  height: 100%;\n  border-left: 1px solid var(--pm-border-soft);\n}\n\n.note-top-lead + .crumbs {\n  margin-left: 0.5rem;\n}\n\n.crumbs {\n  flex: 1;\n  min-width: 0;\n}\n\n.crumbs ol {\n  display: flex;\n  align-items: center;\n  margin: 0;\n  padding: 0;\n  overflow: hidden;\n  list-style: none;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n  white-space: nowrap;\n}\n\n.crumbs li {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  gap: 0.3rem;\n  margin-right: 0.3rem;\n}\n\n.crumbs li .i {\n  opacity: 0.6;\n}\n\n.crumbs li.crumb-notebook .i:first-child {\n  opacity: 1;\n  color: var(--pm-accent);\n}\n\n.crumbs li[aria-current='page'] {\n  flex: 0 1 auto;\n  min-width: 0;\n  display: block;\n  overflow: hidden;\n  color: var(--pm-fg);\n  text-overflow: ellipsis;\n}\n\n.note-actions {\n  display: flex;\n  flex: none;\n  align-items: center;\n  gap: 2px;\n}\n\n.note-top .sep {\n  width: 1px;\n  height: 1.1rem;\n  margin: 0 0.3rem;\n  background: var(--pm-border-strong);\n}\n\n/* Pressed is the accent's tint, so an open panel or the source view reads at a glance. */\n.note-actions .icon-btn[aria-pressed='true'] {\n  background: var(--pm-accent-soft);\n  color: var(--pm-accent);\n}\n\n.btn.quiet {\n  height: var(--pm-control-sm);\n  padding: 0 0.6rem;\n  border-color: transparent;\n  background: transparent;\n  box-shadow: none;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n}\n\n.btn.quiet:hover:not(:disabled) {\n  background: var(--pm-hover);\n  color: var(--pm-fg);\n}\n\n/* A quiet destructive action (Delete for good) is red too, without a fill. */\n.btn.quiet.danger,\n.btn.quiet.danger:hover:not(:disabled) {\n  color: var(--pm-danger);\n}\n\n/*\n * Beside a full button (Cancel by Save, Delete for Good by Restore) a quiet one is as tall, so\n * its hover box is not 4px shorter than its neighbour; as are a symbol's icon buttons, in a row\n * of full-height controls (A988). A minimum, so touch keeps its 44px.\n */\n:is(.capture, .feedback-dlg, .trash, .settings-content)\n  .btn.quiet:is(.btn:not(.quiet) ~ *, :has(~ .btn:not(.quiet))),\n.symbol-actions .btn.quiet {\n  min-height: var(--pm-control);\n}\n\n/* The note header's Copy menu (T15). */\n.menu-anchor {\n  position: relative;\n}\n\n.menu {\n  position: absolute;\n  top: calc(100% + 0.25rem);\n  right: 0;\n  z-index: 40;\n  display: flex;\n  flex-direction: column;\n  min-width: 14rem;\n  padding: 0.25rem;\n  border: 1px solid var(--pm-border);\n  border-radius: 0;\n  background: var(--pm-raised);\n  box-shadow: var(--pm-popover-shadow);\n  animation: pm-rise var(--pm-medium) var(--pm-ease);\n}\n\n.menu-item {\n  display: flex;\n  align-items: center;\n  gap: 0.6rem;\n  min-height: var(--pm-control);\n  padding: 0 0.6rem;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: var(--pm-fg);\n  font: inherit;\n  font-size: var(--pm-text-item);\n  text-align: left;\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.menu-item .i {\n  color: var(--pm-muted);\n}\n\n.menu-item:hover,\n.menu-item:focus {\n  outline: none;\n  background: var(--pm-hover);\n}\n\n.menu-item:focus-visible {\n  box-shadow: inset 0 0 0 2px var(--pm-focus);\n}\n\n.menu-item.danger,\n.menu-item.danger .i {\n  color: var(--pm-danger);\n}\n\n/* The tree's context menu (A570): fixed at the pointer, not under a button. */\n.menu.context-menu {\n  position: fixed;\n  right: auto;\n  z-index: 60;\n}\n\n/* The notes a context menu acts on (review S1): named above its items. */\n.menu-caption {\n  max-width: 18rem;\n  margin: 0;\n  padding: 0.3rem 0.6rem 0.4rem;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-meta);\n  overflow-wrap: anywhere;\n}\n\n/* Selected notes in the tree (A570), and folders picked with them (T68, #230). */\n.tree-row.note-row[aria-selected='true'],\n.tree-row.folder-row[data-picked] {\n  background: var(--pm-accent-soft);\n}\n\n/* The note's actions menu (A575): label, then the command's keys, then On for a toggle. */\n.menu-item .menu-label {\n  flex: 1;\n}\n\n.menu-keys {\n  display: inline-flex;\n  margin-left: 1rem;\n  color: var(--pm-muted);\n}\n\n.menu[data-sheet] .menu-keys {\n  display: none;\n}\n\n.menu-item[aria-checked='true']::after {\n  margin-left: auto;\n  padding-left: 1rem;\n  color: var(--pm-accent);\n  content: 'On';\n  font-size: var(--pm-text-badge);\n  font-weight: var(--pm-weight-badge);\n}\n\n/*\n * A menu with toggles keeps a column for On at the end of every item, empty when off, so the\n * keys line up whether an item is on or not; On used to push its row's keys left (A988).\n */\n.menu:has(> .menu-item[role='menuitemcheckbox']) > .menu-item::after {\n  flex: none;\n  box-sizing: border-box;\n  width: 2.25rem;\n  margin-left: 0;\n  padding-left: 1rem;\n  text-align: right;\n}\n\n.menu:has(> .menu-item[role='menuitemcheckbox']) > .menu-item:not([aria-checked='true'])::after {\n  content: '';\n}\n\n/* A choice (the sort order, T52): a check before the one in use, not On after it. */\n.menu-item[role='menuitemradio'][aria-checked='true']::after {\n  content: none;\n}\n\n.menu-check {\n  display: inline-grid;\n  flex: none;\n  place-items: center;\n  width: 1rem;\n}\n\n.menu-check .i {\n  color: var(--pm-accent);\n}\n\n.menu-sep {\n  height: 1px;\n  margin: 0.3rem 0.5rem;\n  background: var(--pm-border);\n}\n\n.menu-scrim {\n  display: none;\n}\n\n/*\n * The window's toasts (PEN-63): one stack at the bottom centre, newest at the bottom, 8 px\n * apart, at most three. It never takes the pointer; only a toast with controls does (A558).\n */\n.toast-stack {\n  position: fixed;\n  z-index: 80;\n  bottom: calc(1.25rem + env(safe-area-inset-bottom));\n  left: 50%;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 0.5rem;\n  width: max-content;\n  max-width: min(28rem, calc(100vw - 2rem));\n  translate: -50% 0;\n  pointer-events: none;\n}\n\n.toast-slot {\n  display: contents;\n}\n\n/* A raised card in the theme's own colours, square (A976). */\n.toast {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  box-sizing: border-box;\n  max-width: 100%;\n  min-height: 2.5rem;\n  margin: 0;\n  padding: 0.5rem 1rem 0.5rem 0.875rem;\n  overflow-wrap: anywhere;\n  border: 1px solid var(--pm-border-strong);\n  border-radius: 0;\n  background: var(--pm-raised);\n  box-shadow: var(--pm-popover-shadow);\n  color: var(--pm-fg);\n  font-size: var(--pm-text-item);\n  line-height: var(--pm-leading-snug);\n  animation: pm-toast-in var(--pm-medium) var(--pm-ease);\n}\n\n/* Only a toast with controls takes the pointer: a text toast lets a click or drop through. */\n.toast:has(button, a) {\n  pointer-events: auto;\n}\n\n.toast .i {\n  flex: none;\n  color: var(--pm-muted);\n}\n\n/* A check for a success, in the accent; a warning for a refusal or failure, in danger. */\n.toast[data-tone='done'] .toast-glyph,\n.toast .toast-glyph[data-icon='check'] {\n  color: var(--pm-accent);\n}\n\n.toast[data-tone='error'] .toast-glyph,\n.toast .toast-glyph[data-icon='warning'] {\n  color: var(--pm-danger);\n}\n\n/* A toast with an action (A524): Undo after Move to Trash. */\n.toast-with-action {\n  padding-right: 0.25rem;\n}\n\n.toast-action,\n.toast-close {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  min-height: 2rem;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n\n.toast-action {\n  padding: 0 0.6rem;\n  color: var(--pm-accent);\n  font-weight: var(--pm-weight-semibold);\n}\n\n.toast-close {\n  width: 2rem;\n  color: var(--pm-muted);\n}\n\n.toast-close .i {\n  color: inherit;\n}\n\n.toast-action:hover,\n.toast-close:hover {\n  background: var(--pm-hover);\n}\n\n.toast-close:hover {\n  color: var(--pm-fg);\n}\n\n.toast-action:focus-visible,\n.toast-close:focus-visible {\n  outline: none;\n  box-shadow: var(--pm-ring);\n}\n\n@keyframes pm-toast-in {\n  from {\n    opacity: 0;\n    transform: translateY(8px);\n  }\n}\n\n/* Going: it fades. */\n.toast[data-leaving] {\n  opacity: 0;\n  transition: opacity var(--pm-fast) var(--pm-ease);\n}\n\n.note-main:focus {\n  outline: none;\n}\n\n/* Tooltips (T36, A189): one layer, after a control's data-tip (shell/Tooltip.tsx). */\n.tooltip {\n  position: fixed;\n  z-index: 120;\n  max-width: min(18rem, calc(100vw - 1rem));\n  padding: 0.3rem 0.55rem;\n  border-radius: 0;\n  background: var(--pm-fg);\n  box-shadow: var(--pm-popover-shadow);\n  color: var(--pm-bg);\n  font-family: var(--pm-font);\n  font-size: var(--pm-text-tooltip);\n  font-weight: var(--pm-weight-tooltip);\n  line-height: var(--pm-leading-tooltip);\n  pointer-events: none;\n  animation: pm-fade var(--pm-fast) var(--pm-ease);\n}\n\n/* Touch screens have no hover: a control's label is in its sheet, drawer or app bar instead. */\n@media (hover: none) {\n  .tooltip {\n    display: none;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .tooltip,\n  .toast {\n    animation: none;\n  }\n\n  .toast[data-leaving] {\n    opacity: 0;\n    transition: none;\n  }\n}\n\n@keyframes pm-rise {\n  from {\n    opacity: 0;\n    transform: translateY(4px);\n  }\n}\n\n@keyframes pm-pulse {\n  50% {\n    opacity: 0.35;\n  }\n}\n\n/*\n * An inline confirmation's question (ConfirmBlock, PEN-137): a line of its own, in the row\n * label's weight, above the sentence; in a row of buttons it takes the whole first line.\n */\n[role='alertdialog'] > .confirm-block-title {\n  flex-basis: 100%;\n  margin: 0 0 0.25rem;\n  color: var(--pm-fg);\n  font-weight: var(--pm-weight-row-label);\n}\n\n/* apps/web/src/theme/look-settings.css */\n/*\n * Settings → Look and Feel (PEN-146): Appearance, Sidebar, Note and Symbols. Appearance, Sidebar\n * and Note are two tabs, Settings (the controls in groups of rows) and Preview (a live preview of\n * what they change, A1633). The theme editor is its controls beside its preview; on a narrow\n * window (the page's own width under 40rem) the preview goes under them. Every colour is a token.\n */\n.lf-page {\n  container-type: inline-size;\n}\n\n.lf-split {\n  --lf-preview: 20rem;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) var(--lf-preview);\n  gap: 1.5rem;\n  align-items: start;\n  margin-top: 1rem;\n}\n\n/*\n * Settings and Preview (A1633), as Android's Appearance draws them (A1619): two tabs across the\n * page under its header, each with its icon, a line above and below and one between. The one\n * shown has the page's background and the accent under it; the other is darker. They hold still\n * under the pinned header while the page scrolls under them.\n */\n.lf-tabs {\n  --lf-tab-off: color-mix(in oklab, var(--pm-bg), var(--pm-shadow-color) 5%);\n\n  position: sticky;\n  z-index: 3;\n  top: calc(var(--pm-hit) + 1px);\n  display: grid;\n  grid-auto-columns: minmax(0, 1fr);\n  grid-auto-flow: column;\n  margin-top: 1rem;\n  border-block: 1px solid var(--pm-border-soft);\n  background: var(--pm-bg);\n}\n\n:root[data-mode='dark'] .lf-tabs {\n  --lf-tab-off: color-mix(in oklab, var(--pm-bg), var(--pm-shadow-color) 25%);\n}\n\n.lf-tab {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  min-height: var(--pm-hit);\n  padding: 0 1rem;\n  border: 0;\n  border-radius: 0;\n  background: var(--lf-tab-off);\n  color: var(--pm-muted);\n  font: inherit;\n  font-size: var(--pm-text-item);\n  font-weight: var(--pm-weight-semibold);\n  white-space: nowrap;\n  cursor: pointer;\n}\n\n.lf-tab + .lf-tab {\n  border-left: 1px solid var(--pm-border-soft);\n}\n\n.lf-tab:hover {\n  color: var(--pm-fg);\n}\n\n.lf-tab[aria-selected='true'] {\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n}\n\n.lf-tab[aria-selected='true']::after {\n  position: absolute;\n  inset: auto 0 -1px;\n  height: 2px;\n  background: var(--pm-accent);\n  content: '';\n}\n\n.lf-tab:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: -2px;\n}\n\n.lf-tabpanel {\n  min-width: 0;\n  margin-top: 1rem;\n}\n\n.lf-tabpanel[hidden] {\n  display: none;\n}\n\n/* The Preview tab: a line naming what it shows, then the preview as large as the page allows. */\n.lf-preview-panel {\n  --preview-zoom-height: calc(100vh - 16rem);\n\n  display: grid;\n  gap: 0.75rem;\n}\n\n.lf-preview-panel > .lf-help {\n  margin: 0;\n  font-size: var(--pm-text-help);\n}\n\n.lf-preview-panel .app-preview {\n  margin: 0 auto;\n}\n\n.lf-controls {\n  min-width: 0;\n}\n\n/* A group's subhead, its rule running to the column's edge. */\n.lf-sub {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.35rem 0.5rem;\n  margin: 1.5rem 0 0.5rem;\n  color: var(--pm-fg);\n  font-size: var(--pm-text-group-head);\n  font-weight: var(--pm-weight-group-head);\n}\n\n.lf-sub::after {\n  flex: 1 1 2rem;\n  height: 1px;\n  background: var(--pm-border-soft);\n  content: '';\n}\n\n.lf-controls > .lf-sub:first-child {\n  margin-top: 0;\n}\n\n/*\n * The group's name, a heading inside the subhead (A1559). The subhead keeps the place and size\n * `.settings-section h3` gave it while it was the heading itself; the name inside only inherits.\n */\n.settings-section .lf-sub {\n  margin: 2rem 0 0.5rem;\n  font-size: var(--pm-text-lg);\n}\n\n.lf-sub > .lf-sub-name {\n  margin: 0;\n  font: inherit;\n}\n\n.lf-sub-hint {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  font-weight: var(--pm-weight-help);\n}\n\n/*\n * A setting kept on this device alone (A1559): a laptop, its words in the tooltip. Beside the\n * row's label (`lf-row-name`) or after a group's name.\n */\n.lf-row-name {\n  display: inline-flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem;\n}\n\n.lf-scope {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  color: var(--pm-muted);\n  cursor: help;\n}\n\n.lf-scope:hover {\n  color: var(--pm-fg);\n}\n\n/* A bordered list of rows. */\n.lf-group {\n  min-width: 0;\n  margin: 0;\n  padding: 0;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  list-style: none;\n}\n\n.lf-group > * + * {\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n/* Two columns of rows (the title bar's buttons); one on a narrow page. */\n.lf-group-two {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n}\n\n.lf-group-two > * {\n  border-top: 1px solid var(--pm-border-soft);\n}\n\n.lf-group-two > :nth-child(-n + 2) {\n  border-top: 0;\n}\n\n.lf-group-two > :nth-child(even) {\n  border-left: 1px solid var(--pm-border-soft);\n}\n\n/* Each cell one line at any width: icon, name, then its switch at the end. */\n.lf-group-two > .lf-row {\n  flex-wrap: nowrap;\n}\n\n.lf-group-two > .lf-row > .lf-row-text {\n  flex: 1 1 0;\n}\n\n.lf-group-two > .lf-row > .lf-row-control {\n  flex: none;\n}\n\n/* A long name wraps beside its icon, never under it. */\n.lf-group-two .lf-row-label {\n  flex-wrap: nowrap;\n  align-items: flex-start;\n}\n\n.lf-group-two .lf-row-label > .i {\n  flex: none;\n  margin-top: 0.15rem;\n}\n\n.lf-row {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem 0.75rem;\n  min-height: var(--pm-control);\n  padding: 0.5rem 0.75rem;\n}\n\n.lf-row-text {\n  display: grid;\n  flex: 1 1 10rem;\n  gap: 0.15rem;\n  min-width: 0;\n}\n\n.lf-row-label {\n  display: inline-flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4rem;\n  color: var(--pm-fg);\n  font-size: var(--pm-text-row-label);\n  font-weight: var(--pm-weight-row-label);\n}\n\n.lf-row-label .i {\n  color: var(--pm-muted);\n}\n\n.lf-row-help {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n.lf-row-control {\n  display: flex;\n  flex: 0 1 auto;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 0.5rem;\n  min-width: 0;\n  margin-left: auto;\n}\n\n.lf-row-control > .pm-select {\n  width: 12rem;\n}\n\n/* A row's own status or alert, under its help (SettingRow's `extra`). */\n.lf-row-note {\n  margin: 0.2rem 0 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n.lf-row-note[role='alert'] {\n  color: var(--pm-danger);\n}\n\n/* A control's empty value (no hotkey). */\n.lf-none {\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n}\n\n/* A choice that fills its row (Quick Capture's Saves To): the whole row is the radio's label. */\n.lf-choice {\n  cursor: pointer;\n}\n\n.lf-choice:hover {\n  background: var(--pm-hover);\n}\n\n.lf-choice input {\n  flex: none;\n  margin: 0;\n  accent-color: var(--pm-accent);\n}\n\n.lf-choice:has(input:focus-visible) {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: -2px;\n}\n\n.lf-help {\n  margin: 0.5rem 0 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-help);\n  line-height: var(--pm-leading-help);\n}\n\n.lf-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n  margin-top: 0.75rem;\n}\n\n.lf-actions > .lf-help {\n  margin: 0;\n}\n\n/* A switch: a native checkbox drawn as on and off. */\n.lf-switch {\n  position: relative;\n  flex: none;\n  width: 2.1rem;\n  height: 1.2rem;\n  margin: 0;\n  border: 1px solid var(--pm-border-strong);\n  background: var(--pm-sidebar);\n  cursor: pointer;\n  appearance: none;\n  -webkit-appearance: none;\n  transition:\n    background var(--pm-fast),\n    border-color var(--pm-fast);\n}\n\n.lf-switch::before {\n  position: absolute;\n  top: 2px;\n  left: 2px;\n  width: calc(1.2rem - 6px);\n  height: calc(1.2rem - 6px);\n  background: var(--pm-muted);\n  content: '';\n  transition: transform var(--pm-fast);\n}\n\n.lf-switch:checked {\n  border-color: var(--pm-accent);\n  background: var(--pm-accent);\n}\n\n.lf-switch:checked::before {\n  background: var(--pm-on-accent);\n  transform: translateX(0.9rem);\n}\n\n.lf-switch:focus-visible {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 2px;\n}\n\n.lf-switch:disabled {\n  cursor: default;\n  opacity: 0.5;\n}\n\n/* An option under a row's name (Show Notebook Names under Quick Access). */\n.lf-suboption {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  color: var(--pm-fg);\n  cursor: pointer;\n}\n\n.lf-suboption input {\n  margin: 0;\n  accent-color: var(--pm-accent);\n}\n\n/* − 10 + */\n.lf-stepper {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.15rem;\n}\n\n.lf-stepper-value {\n  min-width: 1.75rem;\n  font-size: var(--pm-text-item);\n  font-variant-numeric: tabular-nums;\n  text-align: center;\n}\n\n/* Fields turned on and off as chips; the checkbox covers its chip, so a click lands on it. */\n.lf-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n}\n\n.lf-chip {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  gap: 0.3rem;\n  min-height: var(--pm-control-sm);\n  padding: 0 0.65rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  color: var(--pm-muted);\n  font-size: var(--pm-text-item);\n  transition:\n    background var(--pm-fast),\n    border-color var(--pm-fast),\n    color var(--pm-fast);\n}\n\n.lf-chip input {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  margin: 0;\n  cursor: pointer;\n  opacity: 0;\n}\n\n.lf-chip:hover {\n  border-color: var(--pm-border-strong);\n  color: var(--pm-fg);\n}\n\n.lf-chip:has(input:checked) {\n  border-color: var(--pm-accent-line);\n  background: var(--pm-accent-soft);\n  color: var(--pm-fg);\n}\n\n.lf-chip:has(input:checked) .i {\n  color: var(--pm-accent);\n}\n\n.lf-chip:has(input:focus-visible) {\n  outline: 2px solid var(--pm-focus);\n  outline-offset: 2px;\n}\n\n.lf-chip:has(input:disabled) {\n  opacity: 0.6;\n}\n\n.lf-chip:has(input:disabled) input {\n  cursor: not-allowed;\n}\n\n/* Rows that reorder: a handle, and a line where a dragged row will land. */\n.lf-grip {\n  flex: none;\n  color: var(--pm-muted);\n  cursor: grab;\n}\n\n.lf-grip:active {\n  cursor: grabbing;\n}\n\n[data-reorder-id][data-dragging] {\n  opacity: 0.5;\n}\n\n[data-reorder-id][data-drop='before'] {\n  box-shadow: inset 0 2px 0 var(--pm-accent);\n}\n\n[data-reorder-id][data-drop='after'] {\n  box-shadow: inset 0 -2px 0 var(--pm-accent);\n}\n\n.lf-reorder-item > .lf-row {\n  padding-left: 0.35rem;\n}\n\n/* The preview beside the controls, in sight as the page scrolls, under the pinned header. */\n.lf-preview-col {\n  position: sticky;\n  top: calc(var(--pm-hit) + 0.75rem);\n  display: grid;\n  gap: 0.5rem;\n  min-width: 0;\n}\n\n.lf-label {\n  margin: 0;\n  color: var(--pm-muted);\n  font-size: var(--pm-text-list-head);\n  font-weight: var(--pm-weight-list-head);\n}\n\n.lf-preview-col > .lf-help {\n  margin: 0;\n  font-size: var(--pm-text-help);\n}\n\n.lf-preview-col .app-preview,\n.lf-preview-col .theme-contrast {\n  margin: 0;\n}\n\n.lf-controls .theme-grid {\n  grid-template-columns: repeat(auto-fill, minmax(9.5rem, 1fr));\n  margin-top: 0.75rem;\n}\n\n/* The Sidebar's preview's frame (the Note's is AppPreview's), in the theme's colours. */\n.lf-preview {\n  overflow: hidden;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n  font-family: var(--pm-font);\n}\n\n/*\n * Settings → Sidebar's preview (A1564): the sidebar itself, at its real size and own width on the\n * Preview tab (A1633), cut off at a height with its foot fading out, as a window's sidebar runs on.\n */\n.lf-sidebar-preview {\n  display: block;\n  width: max-content;\n  max-width: 100%;\n  max-height: min(40rem, calc(100vh - 16rem));\n  margin-inline: auto;\n  padding: 0;\n  background: var(--pm-sidebar);\n  mask-image: linear-gradient(to bottom, currentcolor 85%, transparent);\n}\n\n.lf-sidebar-preview > .sidebar {\n  width: var(--lf-sidebar-width);\n  border-right: 0;\n}\n\n/* Settings → Symbols (Show the Keys): each row its handle, keys, glyph, colour and Remove. */\n.symbol-list.lf-group {\n  display: block;\n  margin: 1rem 0;\n}\n\n.symbol-list.lf-group > .symbol-row {\n  flex-wrap: nowrap;\n  padding: 0.35rem 0.6rem 0.35rem 0.35rem;\n}\n\n.symbol-row .glyph-trigger {\n  justify-content: center;\n  width: 2.5rem;\n  padding: 0;\n}\n\n.symbol-row .colour-trigger {\n  justify-content: flex-start;\n  width: 9.5rem;\n}\n\n/* A list item's row (A1632): its icon where a glyph goes, then its name and what it does. */\n.symbol-row .symbol-kind-icon {\n  display: inline-flex;\n  flex: none;\n  align-items: center;\n  justify-content: center;\n  width: 2.5rem;\n  height: var(--pm-control);\n}\n\n.symbol-row .symbol-kind-name {\n  flex: none;\n  width: 9.5rem;\n}\n\n.symbol-row .symbol-kind-does {\n  flex: 0 1 auto;\n  min-width: 0;\n  margin: 0;\n}\n\n/* An emoji's colour can't be changed (A1588): the note beside its disabled colour. */\n.symbol-row .symbol-colour-note {\n  flex: 0 1 auto;\n  min-width: 0;\n  margin: 0;\n}\n\n.symbol-row .symbol-actions {\n  margin-left: auto;\n}\n\n.symbol-foot {\n  flex-wrap: wrap;\n  gap: 0.5rem 0.75rem;\n}\n\n/* Add ▾ opens from the button's left edge: the column clips what hangs left of it (A1632). */\n.symbol-foot .menu {\n  right: auto;\n  left: 0;\n}\n\n.symbol-foot > .lf-help {\n  margin: 0;\n  font-variant-numeric: tabular-nums;\n}\n\n.symbol-foot-end {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.25rem;\n  margin-left: auto;\n}\n\n/* The Text group's rows. */\n.font-control {\n  display: grid;\n  gap: 0.25rem;\n  width: 12rem;\n}\n\n.font-control .pm-select {\n  width: 100%;\n}\n\n.lf-row .font-size-row {\n  flex-wrap: nowrap;\n}\n\n.lf-row .font-size-range {\n  width: 6.5rem;\n  min-width: 0;\n  flex: none;\n}\n\n@container (max-width: 40rem) {\n  .lf-split {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .lf-preview-col {\n    position: static;\n  }\n\n  .lf-group-two {\n    grid-template-columns: minmax(0, 1fr);\n  }\n\n  .lf-group-two > :nth-child(2) {\n    border-top: 1px solid var(--pm-border-soft);\n  }\n\n  .lf-group-two > :nth-child(even) {\n    border-left: 0;\n  }\n\n  .symbol-list.lf-group > .symbol-row {\n    flex-wrap: wrap;\n  }\n}\n\n@media (max-width: 700px), (pointer: coarse) {\n  .lf-row {\n    min-height: var(--pm-hit);\n  }\n\n  .lf-chip {\n    min-height: var(--pm-hit);\n  }\n}\n\n/*\n * The fonts at their real size (A1582), under a preview: each sample is the app's own text (a\n * type role's class, or the note's `.note-body .ProseMirror` and `.doc-title`), its label under\n * it. Nothing here sets a size: the samples take theirs from the roles and the note's scale.\n */\n.type-specimen {\n  display: grid;\n  gap: 0.75rem;\n  min-width: 0;\n  padding: 0.75rem 0.9rem;\n  border: 1px solid var(--pm-border-soft);\n  background: var(--pm-bg);\n  color: var(--pm-fg);\n}\n\n.type-specimen-group {\n  display: grid;\n  gap: 0.5rem;\n  min-width: 0;\n}\n\n.type-specimen-row {\n  display: grid;\n  gap: 0.1rem;\n  min-width: 0;\n}\n\n.type-specimen-row > :first-child {\n  min-width: 0;\n  margin: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.type-specimen-row [data-specimen-label] {\n  color: var(--pm-muted);\n}\n\n/* The sidebar's rows' size (the touch layout's step larger, A1561). */\n.type-specimen-sidebar {\n  font-size: var(--pm-text-sidebar-item);\n}\n\n/* The note's samples in the note's own rules, without a note's height or margins. */\n.type-specimen-note .ProseMirror {\n  display: grid;\n  gap: 0.5rem;\n  min-height: 0;\n}\n\n.type-specimen-note .ProseMirror > .type-specimen-row {\n  margin: 0;\n}\n\n.type-specimen-note .ProseMirror > .type-specimen-row > :first-child,\n.type-specimen-note .ProseMirror p {\n  margin: 0;\n}\n\n.type-specimen-note .doc-title {\n  field-sizing: initial;\n}\n\n/*\n * A preview that opens larger (A1589): one button over the inert preview, the magnifying glass\n * over a soft dim on hover and on keyboard focus; the dialog draws the preview as large as the\n * window leaves room for (`--preview-zoom-height`), at its real size at most.\n */\n.preview-zoom {\n  position: relative;\n  min-width: 0;\n}\n\n.preview-zoom-button {\n  position: absolute;\n  inset: 0;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: var(--pm-fg);\n  cursor: zoom-in;\n  transition: background-color var(--pm-fast) var(--pm-ease);\n}\n\n.preview-zoom-icon {\n  display: grid;\n  place-items: center;\n  width: 2.75rem;\n  height: 2.75rem;\n  border: 1px solid var(--pm-border);\n  background: var(--pm-raised);\n  box-shadow: var(--pm-shadow);\n  opacity: 0;\n  transform: scale(0.92);\n  transition:\n    opacity var(--pm-fast) var(--pm-ease),\n    transform var(--pm-fast) var(--pm-ease);\n}\n\n.preview-zoom-button:hover,\n.preview-zoom-button:focus-visible {\n  background: color-mix(in oklab, var(--pm-scrim) 55%, transparent);\n}\n\n.preview-zoom-button:hover .preview-zoom-icon,\n.preview-zoom-button:focus-visible .preview-zoom-icon {\n  opacity: 1;\n  transform: none;\n}\n\n.preview-zoom-overlay {\n  align-items: center;\n  padding: 1rem;\n}\n\n.dialog.preview-zoom-dialog {\n  width: min(100%, 68rem);\n  max-height: calc(100vh - 2rem);\n}\n\n.preview-zoom-body {\n  --preview-zoom-height: calc(100vh - 8rem);\n\n  min-height: 0;\n  padding: 1rem;\n  overflow: auto;\n  background: var(--pm-bg);\n}\n\n.badge-preview-places.large {\n  display: flex;\n  justify-content: center;\n  zoom: 2;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .preview-zoom-button,\n  .preview-zoom-icon {\n    transition: none;\n  }\n}\n";
